  };
  const observation = { now, bundle: __quietstartCoinOwner };
  let step;
  const browsing = before.state.phase === 'browse' || before.state.phase === 'claiming' &&
    before.state.claimMode === 'quickBrowse' && before.state.claimBacks === 0 &&
    (!before.state.claimSearchTask || before.state.claimSearchSubmitted);
  const panel = before.state.phase === 'panel' || before.state.phase === 'returning';
  if ((browsing || panel) && !before.continuation && coinPolicy.requests(before, now).read) {
    let { value, receipt } = await ctx.actions.select({ queryRefs: ['owner'],
      input: { before, observation, configuredSpec }, idempotencyKey: ctx.run.id + '/' + before.actionSequence });
    if (value?.row) {
      ({ value, receipt } = await ctx.actions.select({ queryRefs: ['owner'],
        input: { before, observation, configuredSpec, pendingRow: value.row },
        idempotencyKey: ctx.run.id + '/' + before.actionSequence }));
